-- CleanDrive: MySQL 8 / MariaDB schema based on supplied ERD
-- Non-destructive: creates missing tables; does not alter existing ones.
-- Passwords must be generated by PHP password_hash(); never store plaintext.
CREATE DATABASE IF NOT EXISTS `cleandrive` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `cleandrive`;

CREATE TABLE IF NOT EXISTS `user` (
  `user_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(100) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `role` ENUM('super_admin','gso','contractor','collector','barangay_gso','resident') NOT NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  `last_login` DATETIME NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `region` (
  `region_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `region_name` VARCHAR(150) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `province` (
  `province_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `region_id` INT UNSIGNED NOT NULL,
  `region_name` VARCHAR(150) NOT NULL,
  CONSTRAINT `fk_province_region` FOREIGN KEY (`region_id`) REFERENCES `region` (`region_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `city` (
  `city_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `province_id` INT UNSIGNED NOT NULL,
  `city_name` VARCHAR(150) NOT NULL,
  CONSTRAINT `fk_city_province` FOREIGN KEY (`province_id`) REFERENCES `province` (`province_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `barangay` (
  `barangay_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `city_id` INT UNSIGNED NOT NULL,
  `barangay_name` VARCHAR(150) NOT NULL,
  CONSTRAINT `fk_barangay_city` FOREIGN KEY (`city_id`) REFERENCES `city` (`city_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `super_admin` (
  `super_admin_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL UNIQUE,
  `password` VARCHAR(255) NULL COMMENT 'Legacy ERD field; authentication uses user.password_hash',
  `contact_name` VARCHAR(150) NOT NULL,
  `contact_no` VARCHAR(30) NULL,
  `email` VARCHAR(190) NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  CONSTRAINT `fk_super_admin_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `gso` (
  `gso_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL UNIQUE,
  `super_admin_id` INT UNSIGNED NOT NULL,
  `city_id` INT UNSIGNED NOT NULL,
  `office_name` VARCHAR(200) NOT NULL,
  `contact_no` VARCHAR(30) NULL,
  `email` VARCHAR(190) NULL,
  `office_address` VARCHAR(255) NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  CONSTRAINT `fk_gso_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_gso_super_admin` FOREIGN KEY (`super_admin_id`) REFERENCES `super_admin` (`super_admin_id`),
  CONSTRAINT `fk_gso_city` FOREIGN KEY (`city_id`) REFERENCES `city` (`city_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `barangay_gso` (
  `barangay_gso_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL UNIQUE,
  `barangay_id` INT UNSIGNED NOT NULL,
  `contact_name` VARCHAR(150) NOT NULL,
  `contact_no` VARCHAR(30) NULL,
  `email` VARCHAR(190) NULL,
  `address` VARCHAR(255) NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  CONSTRAINT `fk_barangay_gso_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_barangay_gso_barangay` FOREIGN KEY (`barangay_id`) REFERENCES `barangay` (`barangay_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `resident` (
  `resident_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL UNIQUE,
  `barangay_id` INT UNSIGNED NOT NULL,
  `first_name` VARCHAR(100) NOT NULL,
  `last_name` VARCHAR(100) NOT NULL,
  `birth_date` DATE NULL,
  `gender` VARCHAR(30) NULL,
  `contact_no` VARCHAR(30) NULL,
  `email` VARCHAR(190) NULL,
  `house_no` VARCHAR(50) NULL,
  `street` VARCHAR(200) NULL,
  CONSTRAINT `fk_resident_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_resident_barangay` FOREIGN KEY (`barangay_id`) REFERENCES `barangay` (`barangay_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `contractor` (
  `contractor_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL UNIQUE,
  `gso_id` INT UNSIGNED NOT NULL,
  `company_name` VARCHAR(200) NOT NULL,
  `business_license_number` VARCHAR(100) NULL,
  `contact_no` VARCHAR(30) NULL,
  `email` VARCHAR(190) NULL,
  `address` VARCHAR(255) NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  CONSTRAINT `fk_contractor_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`),
  CONSTRAINT `fk_contractor_gso` FOREIGN KEY (`gso_id`) REFERENCES `gso` (`gso_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `collector` (
  `collector_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `contractor_id` INT UNSIGNED NOT NULL,
  `user_id` INT UNSIGNED NOT NULL UNIQUE,
  `first_name` VARCHAR(100) NOT NULL,
  `last_name` VARCHAR(100) NOT NULL,
  `contact_no` VARCHAR(30) NULL,
  `email` VARCHAR(190) NULL,
  `license_no` VARCHAR(100) NULL,
  `employment_status` VARCHAR(30) NOT NULL DEFAULT 'active',
  `date_joined` DATE NULL,
  `date_ended` DATE NULL,
  CONSTRAINT `fk_collector_contractor` FOREIGN KEY (`contractor_id`) REFERENCES `contractor` (`contractor_id`),
  CONSTRAINT `fk_collector_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `documentation` (
  `documentation_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `barangay_gso_id` INT UNSIGNED NOT NULL,
  `before_photo` VARCHAR(500) NULL,
  `after_photo` VARCHAR(500) NULL,
  `remarks` TEXT NULL,
  `uploaded_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_documentation_barangay_gso` FOREIGN KEY (`barangay_gso_id`) REFERENCES `barangay_gso` (`barangay_gso_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `complaint` (
  `complaint_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `resident_id` INT UNSIGNED NOT NULL,
  `barangay_gso_id` INT UNSIGNED NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `description` TEXT NOT NULL,
  `image` VARCHAR(500) NULL,
  `complaint_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` VARCHAR(30) NOT NULL DEFAULT 'pending',
  CONSTRAINT `fk_complaint_resident` FOREIGN KEY (`resident_id`) REFERENCES `resident` (`resident_id`),
  CONSTRAINT `fk_complaint_barangay_gso` FOREIGN KEY (`barangay_gso_id`) REFERENCES `barangay_gso` (`barangay_gso_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `complaint_resolution` (
  `resolution_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `complaint_id` INT UNSIGNED NOT NULL,
  `barangay_gso_id` INT UNSIGNED NOT NULL,
  `resolved_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `image` VARCHAR(500) NULL,
  `remarks` TEXT NULL,
  CONSTRAINT `fk_resolution_complaint` FOREIGN KEY (`complaint_id`) REFERENCES `complaint` (`complaint_id`),
  CONSTRAINT `fk_resolution_barangay_gso` FOREIGN KEY (`barangay_gso_id`) REFERENCES `barangay_gso` (`barangay_gso_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `marketplace_item` (
  `item_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `resident_id` INT UNSIGNED NOT NULL,
  `item_name` VARCHAR(200) NOT NULL,
  `description` TEXT NULL,
  `category` VARCHAR(100) NULL,
  `price` DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  `quantity` INT UNSIGNED NOT NULL DEFAULT 1,
  `address` VARCHAR(255) NULL,
  `image` VARCHAR(500) NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'available',
  `posted_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_marketplace_item_resident` FOREIGN KEY (`resident_id`) REFERENCES `resident` (`resident_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `sold_item` (
  `solditem_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `item_id` INT UNSIGNED NOT NULL,
  `sold_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_sold_item_marketplace_item` FOREIGN KEY (`item_id`) REFERENCES `marketplace_item` (`item_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `message` (
  `message_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `sender_id` INT UNSIGNED NOT NULL,
  `receiver_id` INT UNSIGNED NOT NULL,
  `item_id` INT UNSIGNED NOT NULL,
  `message` TEXT NOT NULL,
  `sent_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` VARCHAR(30) NOT NULL DEFAULT 'sent',
  CONSTRAINT `fk_message_sender_resident` FOREIGN KEY (`sender_id`) REFERENCES `resident` (`resident_id`),
  CONSTRAINT `fk_message_receiver_resident` FOREIGN KEY (`receiver_id`) REFERENCES `resident` (`resident_id`),
  CONSTRAINT `fk_message_item` FOREIGN KEY (`item_id`) REFERENCES `marketplace_item` (`item_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `notification` (
  `notification_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(200) NOT NULL,
  `message` TEXT NOT NULL,
  `type` VARCHAR(60) NOT NULL,
  `date_created` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `notification_recipient` (
  `notification_recipient_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `notification_id` INT UNSIGNED NOT NULL,
  `user_id` INT UNSIGNED NOT NULL,
  `is_read` BOOLEAN NOT NULL DEFAULT FALSE,
  `read_at` DATETIME NULL,
  `date_created` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `fk_notification_recipient_notification` FOREIGN KEY (`notification_id`) REFERENCES `notification` (`notification_id`),
  CONSTRAINT `fk_notification_recipient_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `route` (
  `route_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `gso_id` INT UNSIGNED NOT NULL,
  `route_Name` VARCHAR(200) NOT NULL,
  `total_Distance` DECIMAL(10,2) NULL,
  `estimated_Duration` INT UNSIGNED NULL COMMENT 'Duration in minutes',
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  CONSTRAINT `fk_route_gso` FOREIGN KEY (`gso_id`) REFERENCES `gso` (`gso_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `route_stop` (
  `route_stop_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `route_id` INT UNSIGNED NOT NULL,
  `barangay_id` INT UNSIGNED NOT NULL,
  `stop_order` INT UNSIGNED NOT NULL,
  `scheduled_time` TIME NULL,
  `latitude` DECIMAL(10,7) NULL,
  `longitude` DECIMAL(10,7) NULL,
  `estimated_arrival_time` TIME NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  UNIQUE KEY `uq_route_stop_order` (`route_id`, `stop_order`),
  CONSTRAINT `fk_route_stop_route` FOREIGN KEY (`route_id`) REFERENCES `route` (`route_id`),
  CONSTRAINT `fk_route_stop_barangay` FOREIGN KEY (`barangay_id`) REFERENCES `barangay` (`barangay_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `collection_schedule` (
  `collection_schedule_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `route_id` INT UNSIGNED NOT NULL,
  `effective_from` DATE NOT NULL,
  `effective_until` DATE NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'active',
  CONSTRAINT `fk_collection_schedule_route` FOREIGN KEY (`route_id`) REFERENCES `route` (`route_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `schedule_day` (
  `schedule_day_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `collection_schedule_id` INT UNSIGNED NOT NULL,
  `day_of_week` ENUM('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday') NOT NULL,
  UNIQUE KEY `uq_schedule_weekday` (`collection_schedule_id`, `day_of_week`),
  CONSTRAINT `fk_schedule_day_collection_schedule` FOREIGN KEY (`collection_schedule_id`) REFERENCES `collection_schedule` (`collection_schedule_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `vehicle` (
  `vehicle_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `contractor_id` INT UNSIGNED NOT NULL,
  `plate_number` VARCHAR(30) NOT NULL UNIQUE,
  `capacity` DECIMAL(12,2) NULL,
  `vehicle_type` VARCHAR(100) NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'available',
  CONSTRAINT `fk_vehicle_contractor` FOREIGN KEY (`contractor_id`) REFERENCES `contractor` (`contractor_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `collection_assignment` (
  `collection_assignment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `collection_schedule_id` INT UNSIGNED NOT NULL,
  `collector_id` INT UNSIGNED NOT NULL,
  `vehicle_id` INT UNSIGNED NOT NULL,
  `assigned_date` DATE NOT NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'assigned',
  CONSTRAINT `fk_assignment_schedule` FOREIGN KEY (`collection_schedule_id`) REFERENCES `collection_schedule` (`collection_schedule_id`),
  CONSTRAINT `fk_assignment_collector` FOREIGN KEY (`collector_id`) REFERENCES `collector` (`collector_id`),
  CONSTRAINT `fk_assignment_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicle` (`vehicle_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `collection_run` (
  `run_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `schedule_day_id` INT UNSIGNED NOT NULL,
  `collection_assignment_id` INT UNSIGNED NOT NULL,
  `collection_date` DATE NOT NULL,
  `started_at` DATETIME NULL,
  `completed_at` DATETIME NULL,
  `status` VARCHAR(30) NOT NULL DEFAULT 'scheduled',
  CONSTRAINT `fk_run_schedule_day` FOREIGN KEY (`schedule_day_id`) REFERENCES `schedule_day` (`schedule_day_id`),
  CONSTRAINT `fk_run_assignment` FOREIGN KEY (`collection_assignment_id`) REFERENCES `collection_assignment` (`collection_assignment_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `collection_status` (
  `collection_status_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `run_id` INT UNSIGNED NOT NULL,
  `route_stop_id` INT UNSIGNED NOT NULL,
  `final_status` VARCHAR(30) NOT NULL DEFAULT 'pending',
  `actual_arrival_time` DATETIME NULL,
  `actual_departure_time` DATETIME NULL,
  `remarks` TEXT NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_status_run_stop` (`run_id`, `route_stop_id`),
  CONSTRAINT `fk_status_run` FOREIGN KEY (`run_id`) REFERENCES `collection_run` (`run_id`),
  CONSTRAINT `fk_status_route_stop` FOREIGN KEY (`route_stop_id`) REFERENCES `route_stop` (`route_stop_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `collection_status_history` (
  `status_history_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `collection_status_id` INT UNSIGNED NOT NULL,
  `status` VARCHAR(30) NOT NULL,
  `recorded_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reason` VARCHAR(255) NULL,
  `remarks` TEXT NULL,
  CONSTRAINT `fk_status_history_status` FOREIGN KEY (`collection_status_id`) REFERENCES `collection_status` (`collection_status_id`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `vehicle_location` (
  `vehicle_location_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `collection_assignment_id` INT UNSIGNED NOT NULL,
  `latitude` DECIMAL(10,7) NOT NULL,
  `longitude` DECIMAL(10,7) NOT NULL,
  `speed` DECIMAL(9,2) NULL,
  `heading` DECIMAL(6,2) NULL,
  `recorded_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY `idx_vehicle_location_assignment_time` (`collection_assignment_id`, `recorded_at`),
  CONSTRAINT `fk_vehicle_location_assignment` FOREIGN KEY (`collection_assignment_id`) REFERENCES `collection_assignment` (`collection_assignment_id`)
) ENGINE=InnoDB;

-- 30 tables total. This is a schema, not sample data or account inserts.
-- IMPORTANT: Existing tables aren't modified by CREATE TABLE IF NOT EXISTS.
